    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        long[][] products = new long[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); products[i][0] = (long) in.nval;
            in.nextToken(); products[i][1] = (long) in.nval;
        }
        in.nextToken();
        int s = (int) in.nval;
        long[][] sales = new long[s][3];
        for (int i = 0; i < s; i++) {
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                sales[i][j] = (long) in.nval;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (long[] r : summarize(products, sales)) sb.append(r[0]).append(' ').append(r[1]).append(' ').append(r[2]).append('\n');
        System.out.print(sb);
    }
}
